-- =========================================================
-- Regiões de Saúde e Macrorregiões de Saúde (Base Territorial DATASUS, jun/2026)
-- =========================================================
-- Relaciona cada município (do paciente) à sua Região de Saúde e à sua Macrorregião de Saúde,
-- conforme o modelo do enunciado (MUNICIPIO -> RL -> região). A tabela tb_regsaud (nomes das
-- regiões) já é carregada com as demais tabelas territoriais.
--
-- Por que Macrorregião e não Microrregião IBGE: na base territorial de jun/2026, 497 dos 498
-- municípios do RS apontam para o código 43900 em rl_municip_micibge, que não existe em tb_micibge
-- (o IBGE substituiu as microrregiões pelas Regiões Geográficas Imediatas em 2017).
-- Por que rl_municip_macsaud e não rl_regsaud_macsaud: esta última tem uma região repetida
-- (440 linhas, 439 regiões), o que duplicaria registros no JOIN.
--
-- Gerado a partir de: rl_municip_regsaud.csv, rl_municip_macsaud.csv, tb_macsaud.csv
-- Todas as tabelas têm PRIMARY KEY: impede chaves repetidas (ver 05-corrige-s_cid.sql).
-- =========================================================

USE dbsia;

DROP TABLE IF EXISTS rl_municip_regsaud;
CREATE TABLE rl_municip_regsaud (
  co_municip CHAR(6) NOT NULL PRIMARY KEY,
  co_regsaud CHAR(5) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS rl_municip_macsaud;
CREATE TABLE rl_municip_macsaud (
  co_municip CHAR(6) NOT NULL PRIMARY KEY,
  co_macsaud CHAR(4) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS tb_macsaud;
CREATE TABLE tb_macsaud (
  co_macsaud CHAR(4) NOT NULL PRIMARY KEY,
  co_status CHAR(1),
  ds_nome VARCHAR(60),
  ds_nomepad VARCHAR(60),
  ds_abrev VARCHAR(40),
  nu_ordem CHAR(1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- Conferência (esperado: 5572 | 5597 | 168)
SELECT (SELECT COUNT(*) FROM rl_municip_regsaud) AS rl_regsaud,
       (SELECT COUNT(*) FROM rl_municip_macsaud) AS rl_macsaud,
       (SELECT COUNT(*) FROM tb_macsaud) AS macsaud;
